  function render(node, depth) {
    const pad = '  '.repeat(depth)
    const inner = '  '.repeat(depth + 1)
    if (node.kind === 'table') {
      const keys = sortedKeys(node.map)
      if (keys.length === 0) return '{}'
      const parts = keys.map((key) => `${inner}${JSON.stringify(key)}: ${render(node.map.get(key), depth + 1)}`)
      return `{\n${parts.join(',\n')}\n${pad}}`
    }
    if (node.kind === 'array' || node.kind === 'array-of-tables') {
      const items = node.items
      if (items.length === 0) return '[]'
      const parts = items.map((item) => `${inner}${render(item, depth + 1)}`)
      return `[\n${parts.join(',\n')}\n${pad}]`
    }
    return JSON.stringify(node.value)
  }
}

/** Renders one `<path> <type>` line per node below the root, depth first. */
export function toKeys(root) {
  const lines = []
  walk(root, '')
  return lines.map((line) => line + '\n').join('')

  function walk(node, path) {
    if (node.kind === 'table') {
      for (const key of sortedKeys(node.map)) {
        const child = node.map.get(key)
        const childPath = path ? `${path}.${key}` : key
        lines.push(`${childPath} ${typeName(child)}`)
        walk(child, childPath)
      }
    } else if (node.kind === 'array' || node.kind === 'array-of-tables') {
      node.items.forEach((item, index) => {
        const childPath = `${path}[${index}]`
        lines.push(`${childPath} ${typeName(item)}`)
        walk(item, childPath)
      })
    }
  }
}
